module asyn_fifo #(
    parameter DEPTH = 16,
    parameter WIDTH = 8,
    parameter ADDR_WIDTH = $clog2(DEPTH)
) (
    input 					wclk,
    input 					rclk,
    input 					wrstn,
    input					rrstn,
    input 					winc,
    input 			 		rinc,
    input 		[WIDTH-1:0]	wdata,
    output wire				wfull,
    output wire				rempty,
    output wire [WIDTH-1:0]	rdata
);


integer i;
reg [ADDR_WIDTH:0] wptr, rptr, wptr_buff, wptr_syn, rptr_buff, rptr_syn;
reg [WIDTH-1:0] rdata_reg;
wire wen, ren;

dual_port_RAM #(.DEPTH(DEPTH), .WIDTH(WIDTH)) ram(
	.wclk(wclk),
	.wenc(wen),
	.waddr(wptr[ADDR_WIDTH-1:0]),
	.wdata(wdata),
	.rclk(rclk),
	.renc(ren),
	.raddr(rptr[ADDR_WIDTH-1:0]),
	.rdata(rdata_reg)
);

always@(posedge wclk or negedge wrstn) begin
	if(!wrstn) begin
		wptr_buff <= 4'd0;
	end
	else begin
		wptr_buff <= wptr;
	end
end

always@(posedge rclk or negedge rrstn) begin
	if(!rrstn) begin
		rptr_buff <= 4'd0;
	end
	else begin
		rptr_buff <= rptr;
	end
end

always@(posedge wclk or negedge wrstn) begin
	if(!wrstn) begin
		wptr <= 4'd0;
	end
	else begin
		wptr <= wptr + winc;
	end
end

always@(negedge rclk or negedge rrstn) begin
	if(!rrstn) begin
		rptr <= 4'd0;
	end
	else begin
		rptr <= rptr + rinc;
	end
end

always@(posedge rclk or negedge rrstn) begin
	if(!rrstn) begin
		wptr_syn <= 4'd0;
	end
	else begin
		wptr_syn <= wptr_buff;
	end
end

always@(posedge wclk or negedge wrstn) begin
	if(!wrstn) begin
		rptr_syn <= 4'd0;
	end
	else begin
		rptr_syn <= rptr_buff;
	end
end

assign wen = winc && !wfull;
assign ren = rinc && !rempty;
assign wfull = (wptr == {~rptr_syn[ADDR_WIDTH:ADDR_WIDTH-1], rptr_syn[ADDR_WIDTH-2:0]});
assign rempty = (rptr == wptr_syn);

assign rdata = rdata_reg;
endmodule

module dual_port_RAM #(parameter DEPTH = 16,  parameter WIDTH = 8)
(
	 input wclk	,
	 input wenc	,
	 input [$clog2(DEPTH)-1:0] waddr  ,
	 input [WIDTH-1:0] wdata ,
	 input rclk	,
	 input renc	,
	 input [$clog2(DEPTH)-1:0] raddr ,
	 output reg [WIDTH-1:0] rdata 		
);

reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];

always @(posedge wclk) begin
	if(wenc)
		RAM_MEM[waddr] <= wdata;
end 

always @(posedge rclk) begin
	if(renc)
		rdata <= RAM_MEM[raddr];
end 

endmodule
